const raw = $json.intelligence;
const intelligence = typeof raw === 'string' ? JSON.parse(raw) : raw;
const cadence = String(intelligence?.cadence ?? 'unknown').toLowerCase();
const status = intelligence?.status === 'generated' ? 'generated' : 'skipped';
const asOf = new Date(intelligence?.as_of ?? Date.now());
const day = Number.isNaN(asOf.getTime())
  ? new Date().toISOString().slice(0, 10)
  : asOf.toISOString().slice(0, 10);

return {
  event_id: 'SCHED-' + cadence.toUpperCase() + '-' + day + '-' + status.toUpperCase(),
  event_type: 'scheduled_intelligence_' + status,
  reliability_component:
    status === 'generated'
      ? 'scheduled_intelligence'
      : null,
  intelligence
};
